    <title>Computer Languages Quiz</title>
    <style>
      :root {
        color-scheme: light;
        --background: #f5f7fb;
        --card: #ffffff;
        --text: #111827;
        --muted: #5b6474;
        --border: #d9e0ea;
        --border-strong: #b9c4d4;
        --primary: #2457d6;
        --primary-dark: #1d45aa;
        --primary-soft: #eaf0ff;
        --shadow: 0 24px 60px rgba(17, 24, 39, 0.12);
        font-family:
          Inter, ui-sans-serif, system-ui, -apple-system, BlinkMacSystemFont,
          "Segoe UI", sans-serif;
      }

      * {
        box-sizing: border-box;
      }

      body {
        margin: 0;
        min-height: 100vh;
        background:
          radial-gradient(circle at top left, rgba(36, 87, 214, 0.16), transparent 34rem),
          linear-gradient(135deg, #f8fbff 0%, var(--background) 100%);
        color: var(--text);
