        margin: 0 0 0.65rem;
        color: var(--primary);
        font-size: 0.78rem;
        font-weight: 800;
        letter-spacing: 0.12em;
        text-transform: uppercase;
      }

      h1 {
        margin: 0;
        font-size: clamp(2rem, 5vw, 3.25rem);
        line-height: 1.05;
        letter-spacing: -0.05em;
      }

      .intro {
        max-width: 58ch;
        margin: 1rem 0 0;
        color: var(--muted);
        font-size: 1.05rem;
        line-height: 1.6;
      }

      form {
        display: grid;
        gap: 1.25rem;
        padding: 1.5rem;
      }

      .form-field {
        border: 1px solid var(--border);
        border-radius: 22px;
        background: var(--card);
        padding: 1.25rem;
      }

      fieldset {
        min-width: 0;
        margin: 0;
        border: 0;
        padding: 0;
      }

      legend {
        margin-bottom: 0.45rem;
        padding: 0;
        color: var(--text);
        font-size: 1.12rem;
        font-weight: 800;
        line-height: 1.35;
      }

      .help-text {
        margin: 0 0 1rem;
        color: var(--muted);
        font-size: 0.96rem;
        line-height: 1.5;
      }

      .choices {
        display: grid;
        gap: 0.75rem;
        margin-top: 1rem;
      }

      .choice {
        display: grid;
        grid-template-columns: auto 1fr;
        gap: 0.75rem;
        align-items: start;
        min-height: 3.25rem;
        border: 1px solid var(--border);
        border-radius: 16px;
        padding: 0.9rem 1rem;
        background: #fbfcff;
        color: var(--text);
        cursor: pointer;
        transition:
          border-color 160ms ease,
          background-color 160ms ease,
          transform 160ms ease;
      }

      .choice:hover {
        border-color: var(--border-strong);
        transform: translateY(-1px);
      }

      .choice:has(input:checked) {
        border-color: var(--primary);
        background: var(--primary-soft);
      }

      input[type="checkbox"] {
