      input[type="checkbox"]:focus-visible,
      button:focus-visible {
        outline: 3px solid rgba(36, 87, 214, 0.35);
        outline-offset: 3px;
      }

      .actions {
        display: flex;
        flex-wrap: wrap;
        gap: 1rem;
        align-items: center;
        justify-content: space-between;
        padding: 0.5rem 0.25rem 0;
