      button {
        border: 0;
        border-radius: 999px;
        background: var(--primary);
        color: #ffffff;
        padding: 0.95rem 1.45rem;
        font: inherit;
        font-weight: 800;
        cursor: pointer;
        box-shadow: 0 14px 28px rgba(36, 87, 214, 0.28);
      }

      button:hover {
        background: var(--primary-dark);
      }

      .result {
        min-height: 1.5rem;
        margin: 0;
        color: var(--muted);
        font-weight: 700;
