          padding: 1.25rem;
        }

        .form-field {
          padding: 1rem;
        }
      }
    </style>
  </head>
  <body>
    <main id="app"></main>

    <script>
      const questions = [
        {
          id: "language-type",
          prompt: "Which of these are programming languages?",
          helpText: "Select every option that is a programming language. More than one answer may be correct.",
          choices: ["Python", "HTML", "Java", "French"]
        },
        {
          id: "web-languages",
          prompt: "Which languages are commonly used to build interactive websites?",
          choices: ["JavaScript", "CSS", "SQL", "Ruby"]
        },
        {
          id: "compiled-languages",
          prompt: "Which of these languages are commonly compiled before running?",
          choices: ["C", "Go", "Swift", "Markdown"]
        }
      ];

      function Choice({ questionId, choice }) {
        const choiceId = `${questionId}-${choice.toLowerCase().replace(/[^a-z0-9]+/g, "-")}`;

        return `
          <label class="choice" for="${choiceId}">
            <input id="${choiceId}" name="${questionId}" value="${choice}" type="checkbox">
            <span>${choice}</span>
          </label>
        `;
      }

      function Question({ id, prompt, helpText, choices }, index) {
        const helpId = `${id}-help`;
        const helpMarkup = helpText
          ? `<p class="help-text" id="${helpId}">${helpText}</p>`
          : "";
        const describedBy = helpText ? ` aria-describedby="${helpId}"` : "";

        return `
          <div class="form-field">
            <fieldset${describedBy}>
              <legend>${index + 1}. ${prompt}</legend>
              ${helpMarkup}
              <div class="choices">
                ${choices.map((choice) => Choice({ questionId: id, choice })).join("")}
              </div>
            </fieldset>
          </div>
        `;
      }

      function QuizApp() {
        return `
          <section class="quiz-shell" aria-labelledby="quiz-title">
            <div class="hero">
              <p class="eyebrow">Computer languages</p>
              <h1 id="quiz-title">Quick multi-select quiz</h1>
              <p class="intro">
                Test your knowledge of computer languages. Each question can have multiple selected answers.
              </p>
            </div>
            <form id="quiz-form">
              ${questions.map(Question).join("")}
              <div class="actions">
                <button type="submit">Submit answers</button>
                <p class="result" id="quiz-result" role="status" aria-live="polite"></p>
              </div>
            </form>
          </section>
        `;
      }

      document.querySelector("#app").innerHTML = QuizApp();

      document.querySelector("#quiz-form").addEventListener("submit", (event) => {
        event.preventDefault();

        const answeredCount = questions.filter(({ id }) => {
          return document.querySelectorAll(`input[name="${id}"]:checked`).length > 0;
        }).length;

        const result = document.querySelector("#quiz-result");
        result.textContent = `You answered ${answeredCount} of ${questions.length} questions.`;
      });
    </script>
  </body>
</html>
